import{_ as o,o as d,c,a5 as t}from"./chunks/framework.DJo0M80U.js";const m=JSON.parse('{"title":"日期时间类","description":"","frontmatter":{"title":"日期时间类","date":"2026-07-03T00:00:00.000Z","categories":["Java 快速入门"],"tags":["Java","核心API","OneNote"],"lastUpdated":false},"headers":[],"relativePath":"posts/java快速入门/第三部分：核心 API/01-常用 API/日期时间类.md","filePath":"posts/java快速入门/第三部分：核心 API/01-常用 API/日期时间类.md"}'),a={name:"posts/java快速入门/第三部分：核心 API/01-常用 API/日期时间类.md"};function l(i,e,p,r,n,s){return d(),c("div",null,[...e[0]||(e[0]=[t('<div><p><code>## 2.1 Date</code><strong>类</strong><code>###</code> <strong>概述</strong><code>` java.util.Date`</code>类 表示特定的瞬间，精确到毫秒。 继续查阅<code>Date</code>类的描述，发现<code>Date</code>拥有多个构造函数，只是部分已经过时，但是其中有未过时的构造函数可以把毫秒值转成日期对象。</p><ul><li><p><code>public Date()</code> ：分配<code>Date</code>对象并初始化此对象，以表示分配它的时间（精确到毫秒）。</p></li><li><p><code>public Date(long date)</code> ：分配<code>Date</code>对象并初始化此对象，以表示自从标准基准时间（称为<code>“</code>历元（<code>epoch</code>）<code>”</code>，即<code>1970</code>年<code>1</code>月<code>1</code>日<code>00:00:00 GMT</code>）以来的指定毫秒数。</p></li></ul><p><code>\\&gt; tips:</code></p><p>由于我们处于东八区，所以我们的基准时间为<code>1970</code>年<code>1</code>月<code>1</code>日<code>8</code>时<code>0</code>分<code>0</code>秒。</p><p>简单来说：使用无参构造，可以自动设置当前系统时间的毫秒时刻；指定<code>long</code>类型的构造参数，可以自定义毫秒时刻。例如：</p><p>java import java.util.Date; public class Demo01Date { public static void main(String[] args) { // <code>创建日期对象，把当前的时间</code> System.out.println(new Date()); // Tue Jan 16 14:37:35 CST 2018 // <code>创建日期对象，把当前的毫秒值转成日期对象</code> System.out.println(new Date(0L)); // Thu Jan 01 08:00:00 CST 1970 } } <code>\\&gt; tips:</code></p><p>在使用<code>println</code>方法时，会自动调用<code>Date</code>类中的<code>toString</code>方法。 <code>Date</code>类对<code>Object</code>类中的<code>toString</code>方法进行了覆盖重写，所以结果为指定格式的字符串。</p><ul><li>&gt;</li><li><h3 id="" tabindex="-1"><a class="header-anchor" href="#" aria-label="Permalink to &quot;&quot;">​</a></h3></li></ul><p><strong>常用方法</strong><code>Date</code>类中的多数方法已经过时，常用的方法有：</p><ul><li><code>public long getTime()</code> 把日期对象转换成对应的时间毫秒值。 <code>## 2.2 DateFormat</code><strong>类</strong></li></ul><p><code>java.text.DateFormat</code></p><p>是日期<code>/</code>时间格式化子类的抽象类，我们通过这个类可以帮我们完成日期和文本之间的转换<code>,</code>也就是可以在<code>Date</code>对象与<code>String</code>对象之间进行来回转换。</p><p><code>* **</code></p><p><strong>格式化</strong><code>**</code>：按照指定的格式，从<code>Date</code>对象转换为<code>String</code>对象。</p><p><code>* **</code></p><p><strong>解析</strong><code>**</code>：按照指定的格式，从<code>String</code>对象转换为<code>Date</code>对象。 <code>###</code> <strong>构造方法</strong> 由于<code>DateFormat</code>为抽象类，不能直接使用，所以需要常用的子类<code>`java.text.SimpleDateFormat`</code>。 这个类需要一个模式（格式）来指定格式化或解析的标准。构造方法为：</p><ul><li><code>public SimpleDateFormat(String pattern)</code> ：用给定的模式和默认语言环境的日期格式符号构造<code>SimpleDateFormat</code>。 参数<code>pattern</code>是一个字符串，代表日期时间的自定义格式。 <code>###</code> <strong>格式规则</strong> 常用的格式规则为： <code>|</code> 标识字母（区分大小写） <code>|</code> 含义</li></ul><ul><li>|</li><li>| ----------- | ---- |</li><li>| y |</li></ul><p>年</p><ul><li>|</li><li>| M |</li></ul><p>月</p><ul><li>|</li><li>| d |</li></ul><p>日</p><ul><li>|</li><li>| H |</li></ul><p>时</p><ul><li>|</li><li>| m |</li></ul><p>分</p><ul><li>|</li><li>| s |</li></ul><p>秒</p><ul><li>|</li><li>&gt;</li></ul><p>备注：更详细的格式规则，可以参考<code>SimpleDateFormat</code>类的<code>API</code>文档<code>0</code>。 创建<code>SimpleDateFormat</code>对象的代码如：</p><p>java import java.text.DateFormat; import java.text.SimpleDateFormat; public class Demo02SimpleDateFormat { public static void main(String[] args) { // <code>对应的日期格式如：</code> 2018-01-16 15:06:38 DateFormat format = new SimpleDateFormat(&quot;yyyy-MM-dd HH:mm:ss&quot;); } } <code>###</code></p><p><strong>常用方法</strong><code>DateFormat</code>类的常用方法有：</p><ul><li><p><code>public String format(Date date)</code> ：将<code>Date</code>对象格式化为字符串。</p></li><li><p><code>public Date parse(String source)</code> ：将字符串解析为<code>Date</code>对象。 <code>#### format</code><strong>方法</strong> 使用<code>format</code>方法的代码为：</p></li></ul><p>java import java.text.DateFormat; import java.text.SimpleDateFormat; import java.util.Date; /* <code>把</code>Date<code>对象转换成</code> String */ public class Demo03DateFormatMethod { public static void main(String[] args) { Date date = new Date(); // <code>创建日期格式化对象</code>,<code>在获取格式化对象时可以指定风格</code> DateFormat df = new SimpleDateFormat(&quot;yyyy <code>年</code>MM<code>月</code>dd<code>日</code> &quot;); String str = df.format(date); System.out.println(str); // 2008 <code>年</code>1<code>月</code>23<code>日</code> } } <code>#### parse</code></p><p><strong>方法</strong> 使用<code>parse</code>方法的代码为：</p><p>java import java.text.DateFormat; import java.text.ParseException; import java.text.SimpleDateFormat; import java.util.Date; /* <code>把</code>String<code>转换成</code>Date<code>对象</code> */ public class Demo04DateFormatMethod { public static void main(String[] args) throws ParseException { DateFormat df = new SimpleDateFormat(&quot;yyyy <code>年</code>MM<code>月</code>dd<code>日</code> &quot;); String str = &quot;2018 <code>年</code>12<code>月</code>11<code>日</code> &quot;; Date date = df.parse(str); System.out.println(date); // Tue Dec 11 00:00:00 CST 2018 } } <code>## 2.3</code></p><p><strong>练习</strong> 请使用日期时间相关的<code>API</code>，计算出一个人已经出生了多少天。 <code>**</code><strong>思路：</strong></p><ul><li>**</li><li><ol><li></li></ol></li></ul><p>获取当前时间对应的毫秒值 <code>2.</code>获取自己出生日期对应的毫秒值 <code>3.</code>两个时间相减（当前时间</p><p><code>–</code></p><p>出生日期） <code>**</code><strong>代码实现：</strong></p><p><code>**</code>java public static void function() throws Exception {     System.out.println(&quot; <code>请输入出生日期 格式</code> YYYY-MM-dd&quot;);     // <code>获取出生日期</code>,<code>键盘输入</code>     String birthdayString = new Scanner(System.in).next();     // <code>将字符串日期</code>,<code>转成</code>Date<code>对象</code>     // <code>创建</code>SimpleDateFormat<code>对象</code>,<code>写日期模式</code>     SimpleDateFormat sdf = new SimpleDateFormat(&quot;yyyy-MM-dd&quot;);     // <code>调用方法</code>parse,<code>字符串转成日期对象</code>     Date birthdayDate = sdf.parse(birthdayString);       // <code>获取今天的日期对象</code>     Date todayDate = new Date();         // <code>将两个日期转成毫秒值</code>,Date<code>类的方法</code> getTime     long birthdaySecond = birthdayDate.getTime();     long todaySecond = todayDate.getTime();     long secone = todaySecond-birthdaySecond;        if (secone &lt; 0){         System.out.println(&quot; <code>还没出生呢</code> &quot;);     } else {         System.out.println(secone/1000/60/60/24);     } }</p><p><code>## 2.4 Calendar</code><strong>类</strong><code>`java.util.Calendar`</code>是日历类，在<code>Date</code>后出现，替换掉了许多<code>Date</code>的方法。该类将所有可能用到的时间信息封装为静态成员变量，方便获取。日历类就是方便获取各个时间属性的。 <code>###</code> <strong>获取方式</strong><code>Calendar</code>为抽象类，由于语言敏感性，<code>Calendar</code>类在创建对象时并非直接创建，而是通过静态方法创建，返回子类对象，如下： <code>Calendar</code>静态方法</p><ul><li><code>public static Calendar getInstance()</code> ：使用默认时区和语言环境获得一个日历 例如：</li></ul><p>java import java.util.Calendar; public class Demo06CalendarInit { public static void main(String[] args) { Calendar cal = Calendar.getInstance(); } } <code>###</code></p><p><strong>常用方法</strong> 根据<code>Calendar</code>类的<code>API</code>文档，常用方法有：</p><ul><li><p><code>public int get(int field)</code> ：返回给定日历字段的值。</p></li><li><p><code>public void set(int field, int value)</code> ：将给定的日历字段设置为给定值。</p></li><li><p><code>public abstract void add(int field, int amount)</code> ：根据日历的规则，为给定的日历字段添加或减去指定的时间量。</p></li><li><p><code>public Date getTime()</code> ：返回一个表示此<code>Calendar</code>时间值（从历元到现在的毫秒偏移量）的<code>Date</code>对象。</p></li></ul><p><code>Calendar</code>类中提供很多成员常量，代表给定的日历字段： <code>|</code> 字段值 <code>|</code> 含义</p><ul><li>|</li><li>| ------------ | -------------------- |</li><li>| YEAR |</li></ul><p>年</p><ul><li>|</li><li>| MONTH |</li></ul><p>月（从<code>0</code>开始，可以<code>+1</code>使用）</p><ul><li>|</li><li>| DAY_OF_MONTH |</li></ul><p>月中的天（几号）</p><ul><li>|</li><li>| HOUR |</li></ul><p>时（<code>12</code>小时制）</p><ul><li>|</li><li>| HOUR_OF_DAY |</li></ul><p>时（<code>24</code>小时制）</p><ul><li>|</li><li>| MINUTE |</li></ul><p>分</p><ul><li>|</li><li>| SECOND |</li></ul><p>秒</p><ul><li>|</li><li>| DAY_OF_WEEK |</li></ul><p>周中的天（周几，周日为<code>1</code>，可以<code>-1</code>使用）</p><ul><li>|</li><li><h4 id="get-set" tabindex="-1">get/set <a class="header-anchor" href="#get-set" aria-label="Permalink to &quot;get/set&quot;">​</a></h4></li></ul><p><strong>方法</strong><code>get</code>方法用来获取指定字段的值，<code>set</code>方法用来设置指定字段的值，代码使用演示：</p><p>java import java.util.Calendar; public class CalendarUtil { public static void main(String[] args) { // <code>创建</code>Calendar<code>对象</code> Calendar cal = Calendar.getInstance(); // <code>设置年</code></p><p>int year = cal.get(Calendar.YEAR); // <code>设置月</code> int month = cal.get(Calendar.MONTH) + 1; // <code>设置日</code> int dayOfMonth = cal.get(Calendar.DAY_OF_MONTH); System.out.print(year + &quot; <code>年</code> &quot; + month + &quot; <code>月</code> &quot; + dayOfMonth + &quot; <code>日</code> &quot;); } } java import java.util.Calendar; public class Demo07CalendarMethod { public static void main(String[] args) { Calendar cal = Calendar.getInstance(); cal.set(Calendar.YEAR, 2020); System.out.print(year + &quot; <code>年</code> &quot; + month + &quot; <code>月</code> &quot; + dayOfMonth + &quot; <code>日</code> &quot;); // 2020 <code>年</code>1<code>月</code>17<code>日</code> } } <code>#### add</code></p><p><strong>方法</strong><code>add</code>方法可以对指定日历字段的值进行加减操作，如果第二个参数为正数则加上偏移量，如果为负数则减去偏移量。代码如：</p><p>java import java.util.Calendar; public class Demo08CalendarMethod { public static void main(String[] args) { Calendar cal = Calendar.getInstance(); System.out.print(year + &quot; <code>年</code> &quot; + month + &quot; <code>月</code> &quot; + dayOfMonth + &quot; <code>日</code> &quot;); // 2018 年<code>1</code>月<code>17</code>日 <code>//</code> 使用<code>add</code>方法</p><p>cal.add(Calendar.DAY_OF_MONTH, 2); // <code>加</code>2<code>天</code> cal.add(Calendar.YEAR, -3); // <code>减</code>3<code>年</code> System.out.print(year + &quot; <code>年</code> &quot; + month + &quot; <code>月</code> &quot; + dayOfMonth + &quot; <code>日</code> &quot;); // 2015 <code>年</code>1<code>月</code>18<code>日</code> ; } } <code>#### getTime</code></p><p><strong>方法</strong><code>Calendar</code>中的<code>getTime</code>方法并不是获取毫秒时刻，而是拿到对应的<code>Date</code>对象。</p><p>java import java.util.Calendar; import java.util.Date; public class Demo09CalendarMethod { public static void main(String[] args) { Calendar cal = Calendar.getInstance(); Date date = cal.getTime(); System.out.println(date); // Tue Jan 16 16:03:09 CST 2018 } } <code>\\&gt;</code></p><p>小贴士：</p><p><code>\\&gt; ​</code></p><p>西方星期的开始为周日，中国为周一。</p><p><code>\\&gt; ​</code></p><p>在<code>Calendar</code>类中，月份的表示是以<code>0-11</code>代表<code>1-12</code>月。</p><p><code>\\&gt; ​</code></p><p>日期是有大小关系的，时间靠后，时间越大。</p></div>',1)])])}const g=o(a,[["render",l]]);export{m as __pageData,g as default};
